mapper.sql:
CASE WHEN d.current_version_id IS NULL THEN 'UNPUBLISHED'

    WHEN lower(v.file_name) LIKE #{rule.pattern} AND lower(v.mime_type) = #{rule.mime} THEN #{rule.type}

ELSE 'OTHER' END

FROM kb_document d LEFT JOIN kb_document_version v ON v.id = d.current_version_id
WHERE d.status NOT IN ('deleted', 'archived') AND d.security_level <= #{clearance}
AND 
AND 
AND d.title ILIKE #{titlePattern} ESCAPE '\'
AND d.space_id = #{query.spaceId}
AND d.category_id IS NULL

    AND d.category_id IN (
        WITH RECURSIVE descendants AS (
            SELECT id FROM kb_document_category WHERE id = #{query.categoryId} AND space_id = d.space_id
            UNION
            SELECT c.id FROM kb_document_category c JOIN descendants p ON c.parent_id = p.id
            WHERE c.space_id = d.space_id
        ) SELECT id FROM descendants
    )


    AND EXISTS (SELECT 1 FROM kb_document_tag_relation r WHERE r.document_id = d.id AND r.tag_id = #{tag})

AND () = #{query.fileType}
AND d.updated_at >= #{query.updatedFrom}
AND d.updated_at < #{query.updatedTo}

mapper.select:

SELECT ,
    d.category_id, d.metadata_version

ORDER BY d.updated_at DESC, d.id DESC LIMIT #{query.size} OFFSET #{query.offset}
